//! Offline CSR enrollment. Device keys are generated by the client; the
//! operator receives only a proof-of-possession CSR and returns a certificate.
use super::registry::{validate_device_id, DeviceRecord};
use rand::RngCore;
use rcgen::{
    CertificateParams, CertificateSigningRequestParams, DistinguishedName, DnType,
    ExtendedKeyUsagePurpose, IsCa, KeyPair, KeyUsagePurpose, PublicKeyData,
};
use rustls::pki_types::{pem::PemObject, CertificateDer, UnixTime};
use sha2::{Digest, Sha256};
use std::io;
use std::time::Duration;
use zeroize::Zeroizing;

#[path = "enrollment_protocol.rs"]
pub mod protocol;

#[cfg(test)]
#[path = "enrollment_response_tests.rs"]
mod response_tests;

fn invalid(message: &'static str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidInput, message)
}

pub use crate::secret_file::{trusted_parent, write_private_new};

pub struct DeviceCsr {
    pub private_key_pem: Zeroizing<String>,
    pub csr_pem: String,
}

pub fn new_invitation_token() -> Zeroizing<String> {
    let mut bytes = Zeroizing::new([0u8; 32]);
    rand::rngs::OsRng.fill_bytes(&mut *bytes);
    Zeroizing::new(hex::encode(bytes.as_slice()))
}

pub fn generate_csr(device_id: &str) -> io::Result<DeviceCsr> {
    validate_device_id(device_id)?;
    let key = KeyPair::generate_for(&rcgen::PKCS_ED25519)
        .map_err(|_| invalid("device key generation failed"))?;
    let mut params = CertificateParams::new(Vec::<String>::new())
        .map_err(|_| invalid("CSR parameters invalid"))?;
    params.distinguished_name = DistinguishedName::new();
    params
        .distinguished_name
        .push(DnType::CommonName, device_id);
    let csr = params
        .serialize_request(&key)
        .map_err(|_| invalid("device CSR creation failed"))?;
    Ok(DeviceCsr {
        private_key_pem: Zeroizing::new(key.serialize_pem()),
        csr_pem: csr
            .pem()
            .map_err(|_| invalid("device CSR encoding failed"))?,
    })
}

/// Resume an enrollment using the device's existing key, never a replacement.
pub fn csr_for_key(device_id: &str, key_pem: &str) -> io::Result<String> {
    validate_device_id(device_id)?;
    let key = KeyPair::from_pem(key_pem).map_err(|_| invalid("device key invalid"))?;
    if key.algorithm() != &rcgen::PKCS_ED25519 {
        return Err(invalid("device enrollment requires an Ed25519 key"));
    }
    let mut params = CertificateParams::new(Vec::<String>::new())
        .map_err(|_| invalid("CSR parameters invalid"))?;
    params.distinguished_name = DistinguishedName::new();
    params
        .distinguished_name
        .push(DnType::CommonName, device_id);
    params
        .serialize_request(&key)
        .and_then(|csr| csr.pem())
        .map_err(|_| invalid("device CSR creation failed"))
}

fn public_certificates(bytes: &[u8]) -> io::Result<Vec<CertificateDer<'static>>> {
    if bytes.len() > 64 * 1024 {
        return Err(invalid("certificate PEM exceeds limit"));
    }
    let mut text =
        std::str::from_utf8(bytes).map_err(|_| invalid("certificate PEM encoding invalid"))?;
    let mut certificates = Vec::new();
    const BEGIN: &str = "-----BEGIN CERTIFICATE-----";
    const END: &str = "-----END CERTIFICATE-----";
    loop {
        text = text.trim_start();
        if text.is_empty() {
            break;
        }
        if !text.starts_with(BEGIN) || certificates.len() >= 8 {
            return Err(invalid(
                "only a bounded public certificate chain is accepted",
            ));
        }
        let end = text
            .find(END)
            .ok_or_else(|| invalid("certificate PEM is incomplete"))?
            + END.len();
        certificates.push(
            CertificateDer::from_pem_slice(&text.as_bytes()[..end])
                .map_err(|_| invalid("certificate PEM invalid"))?,
        );
        text = &text[end..];
    }
    if certificates.is_empty() {
        return Err(invalid("certificate chain is empty"));
    }
    Ok(certificates)
}

/// Reject non-certificate material before persisting public issuer inputs.
pub fn validate_public_certificate_chain(pem: &[u8]) -> io::Result<()> {
    public_certificates(pem).map(|_| ())
}

/// The offline response protocol pins a single certificate-signing issuer.
pub fn validate_device_ca(ca_pem: &[u8]) -> io::Result<()> {
    let certificates = public_certificates(ca_pem)?;
    if certificates.len() != 1 {
        return Err(invalid(
            "offline enrollment requires one pinned device issuer CA",
        ));
    }
    for ca in certificates {
        let params = CertificateParams::from_ca_cert_der(&ca)
            .map_err(|_| invalid("device issuer certificate invalid"))?;
        if !matches!(params.is_ca, IsCa::Ca(_))
            || (!params.key_usages.is_empty()
                && !params.key_usages.contains(&KeyUsagePurpose::KeyCertSign))
        {
            return Err(invalid("device issuer must be a certificate-signing CA"));
        }
    }
    Ok(())
}

/// Validate an authority configuration without signing or changing state.
pub fn validate_issuer_key(ca_pem: &[u8], key_pem: &[u8], now: u64) -> io::Result<()> {
    validate_device_ca(ca_pem)?;
    if key_pem.len() > 64 * 1024 {
        return Err(invalid("issuer key exceeds limit"));
    }
    let certificates = public_certificates(ca_pem)?;
    let ca = CertificateParams::from_ca_cert_der(&certificates[0])
        .map_err(|_| invalid("issuer certificate invalid"))?;
    let signed_now = i64::try_from(now).map_err(|_| invalid("issuer clock invalid"))?;
    if signed_now < ca.not_before.unix_timestamp() || signed_now >= ca.not_after.unix_timestamp() {
        return Err(invalid("issuer is outside its validity period"));
    }
    let key = rustls::pki_types::PrivateKeyDer::from_pem_slice(key_pem)
        .map_err(|_| invalid("issuer private key invalid"))?;
    let certified = rustls::sign::CertifiedKey::from_der(certificates, key, &super::provider())
        .map_err(|_| invalid("issuer certificate and key do not match"))?;
    certified
        .keys_match()
        .map_err(|_| invalid("issuer key match cannot be established"))
}

/// Check the public response against an independently provisioned CA, the
/// local private key, and the requested device identity. No unknown key-match
/// result is accepted, even if a provider would normally allow it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ValidatedDeviceCertificate {
    pub fingerprint: String,
    pub not_before_unix_secs: u64,
    pub not_after_unix_secs: u64,
    pub public_key: [u8; 32],
}

/// Validate signed identity metadata at its declared start. This supports
/// expired-identity status/recovery; it is deliberately NOT current authorization.
pub fn device_certificate_metadata(
    device_id: &str,
    certificate_pem: &[u8],
    ca_pem: &[u8],
) -> io::Result<ValidatedDeviceCertificate> {
    let certificates = public_certificates(certificate_pem)?;
    let params = CertificateParams::from_ca_cert_der(&certificates[0])
        .map_err(|_| invalid("device certificate profile invalid"))?;
    let start = u64::try_from(params.not_before.unix_timestamp())
        .map_err(|_| invalid("device certificate start invalid"))?;
    validate_device_certificate_public(device_id, certificate_pem, ca_pem, start)
}

pub fn validate_device_certificate(
    device_id: &str,
    certificate_pem: &[u8],
    ca_pem: &[u8],
    key_pem: &[u8],
    now: u64,
) -> io::Result<String> {
    if key_pem.len() > 64 * 1024 {
        return Err(invalid("device enrollment input exceeds limit"));
    }
    let facts = validate_device_certificate_public(device_id, certificate_pem, ca_pem, now)?;
    let key_text =
        std::str::from_utf8(key_pem).map_err(|_| invalid("device key encoding invalid"))?;
    let parsed_key = KeyPair::from_pem(key_text).map_err(|_| invalid("device key invalid"))?;
    if parsed_key.algorithm() != &rcgen::PKCS_ED25519 {
        return Err(invalid("device enrollment requires an Ed25519 key"));
    }
    let key = rustls::pki_types::PrivateKeyDer::from_pem_slice(key_pem)
        .map_err(|_| invalid("device key PEM invalid"))?;
    let certified = rustls::sign::CertifiedKey::from_der(
        public_certificates(certificate_pem)?,
        key,
        &super::provider(),
    )
    .map_err(|_| invalid("device certificate and key do not match"))?;
    certified
        .keys_match()
        .map_err(|_| invalid("device key match could not be verified"))?;
    Ok(facts.fingerprint)
}

pub fn validate_device_certificate_public(
    device_id: &str,
    certificate_pem: &[u8],
    ca_pem: &[u8],
    now: u64,
) -> io::Result<ValidatedDeviceCertificate> {
    validate_device_id(device_id)?;
    if [certificate_pem, ca_pem]
        .iter()
        .any(|bytes| bytes.len() > 64 * 1024)
    {
        return Err(invalid("device enrollment input exceeds limit"));
    }
    validate_device_ca(ca_pem)?;
    let certificate_text = std::str::from_utf8(certificate_pem)
        .map_err(|_| invalid("device certificate encoding invalid"))?;
    let params = CertificateParams::from_ca_cert_pem(certificate_text)
        .map_err(|_| invalid("device certificate profile invalid"))?;
    if !matches!(params.is_ca, IsCa::NoCa)
        || params.extended_key_usages != [ExtendedKeyUsagePurpose::ClientAuth]
        || params.key_usages != [KeyUsagePurpose::DigitalSignature]
        || params.distinguished_name.get(&DnType::CommonName)
            != Some(&rcgen::DnValue::Utf8String(device_id.into()))
        || !params.subject_alt_names.is_empty()
        || !(60..=30 * 24 * 3600).contains(&(params.not_after - params.not_before).whole_seconds())
    {
        return Err(invalid(
            "device certificate does not match enrollment profile",
        ));
    }
    let issuer = CertificateParams::from_ca_cert_der(&public_certificates(ca_pem)?[0])
        .map_err(|_| invalid("device issuer certificate invalid"))?;
    let now_signed = i64::try_from(now).map_err(|_| invalid("device enrollment clock invalid"))?;
    if now_signed < issuer.not_before.unix_timestamp()
        || now_signed >= issuer.not_after.unix_timestamp()
        || params.not_after > issuer.not_after
    {
        return Err(invalid(
            "device issuer validity or device lifetime rejected",
        ));
    }
    let certificates = public_certificates(certificate_pem)?;
    let mut roots = rustls::RootCertStore::empty();
    for ca in public_certificates(ca_pem)? {
        roots
            .add(ca)
            .map_err(|_| invalid("device CA trust anchor invalid"))?;
    }
    let provider = super::provider();
    rustls::server::WebPkiClientVerifier::builder_with_provider(
        std::sync::Arc::new(roots),
        provider.clone(),
    )
    .build()
    .map_err(|_| invalid("device CA verifier invalid"))?
    .verify_client_cert(
        &certificates[0],
        &certificates[1..],
        UnixTime::since_unix_epoch(Duration::from_secs(now)),
    )
    .map_err(|_| invalid("device certificate chain or validity rejected"))?;
    let fingerprint = hex::encode(Sha256::digest(certificates[0].as_ref()));
    let parsed = rustls::server::ParsedCertificate::try_from(&certificates[0])
        .map_err(|_| invalid("device public key invalid"))?;
    let spki = rcgen::SubjectPublicKeyInfo::from_der(parsed.subject_public_key_info().as_ref())
        .map_err(|_| invalid("device public key invalid"))?;
    if spki.algorithm() != &rcgen::PKCS_ED25519 {
        return Err(invalid("device enrollment requires an Ed25519 key"));
    }
    Ok(ValidatedDeviceCertificate {
        fingerprint,
        not_before_unix_secs: u64::try_from(params.not_before.unix_timestamp())
            .map_err(|_| invalid("device certificate start invalid"))?,
        not_after_unix_secs: u64::try_from(params.not_after.unix_timestamp())
            .map_err(|_| invalid("device certificate expiry invalid"))?,
        public_key: spki
            .der_bytes()
            .try_into()
            .map_err(|_| invalid("device public key invalid"))?,
    })
}

pub struct IssuedDevice {
    pub certificate_pem: String,
    pub record: DeviceRecord,
}

/// Verify CSR proof of possession; replace every requested identity/usage/CA
/// extension with the operator's client-only profile. Never accept a CA CSR as
/// authority to issue a CA certificate or arbitrary server identities.
pub fn sign_csr(
    device_id: &str,
    csr_pem: &str,
    ca_pem: &str,
    ca_key_pem: &str,
    now: u64,
    lifetime_secs: u64,
) -> io::Result<IssuedDevice> {
    validate_device_id(device_id)?;
    if !(60..=30 * 24 * 3600).contains(&lifetime_secs) || csr_pem.len() > 64 * 1024 {
        return Err(invalid(
            "device certificate lifetime must be 60 seconds..30 days and CSR bounded",
        ));
    }
    let mut csr = CertificateSigningRequestParams::from_pem(csr_pem)
        .map_err(|_| invalid("CSR signature or encoding invalid"))?;
    let ca_params = CertificateParams::from_ca_cert_pem(ca_pem)
        .map_err(|_| invalid("issuer certificate invalid"))?;
    if !matches!(ca_params.is_ca, IsCa::Ca(_))
        || (!ca_params.key_usages.is_empty()
            && !ca_params.key_usages.contains(&KeyUsagePurpose::KeyCertSign))
    {
        return Err(invalid("issuer must be a certificate-signing CA"));
    }
    let now_i64 = i64::try_from(now).map_err(|_| invalid("enrollment clock invalid"))?;
    if now_i64 < ca_params.not_before.unix_timestamp()
        || now_i64 >= ca_params.not_after.unix_timestamp()
    {
        return Err(invalid("issuer certificate is outside its validity period"));
    }
    let not_after = now
        .checked_add(lifetime_secs)
        .ok_or_else(|| invalid("certificate expiry overflow"))?;
    if not_after > ca_params.not_after.unix_timestamp() as u64 {
        return Err(invalid("device certificate cannot outlive its issuer"));
    }
    let issuer_key = KeyPair::from_pem(ca_key_pem).map_err(|_| invalid("issuer key invalid"))?;
    let issuer = ca_params
        .self_signed(&issuer_key)
        .map_err(|_| invalid("issuer reconstruction failed"))?;
    let mut params = CertificateParams::new(Vec::<String>::new())
        .map_err(|_| invalid("device certificate parameters invalid"))?;
    params.distinguished_name = DistinguishedName::new();
    params
        .distinguished_name
        .push(DnType::CommonName, device_id);
    params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
    params.extended_key_usages = vec![ExtendedKeyUsagePurpose::ClientAuth];
    params.is_ca = IsCa::NoCa;
    params.not_before = time::OffsetDateTime::from_unix_timestamp(now_i64)
        .map_err(|_| invalid("certificate start invalid"))?;
    params.not_after = time::OffsetDateTime::from_unix_timestamp(not_after as i64)
        .map_err(|_| invalid("certificate expiry invalid"))?;
    let mut serial = [0u8; 20];
    rand::rngs::OsRng.fill_bytes(&mut serial);
    serial[0] &= 0x7f;
    serial[19] |= 1;
    params.serial_number = Some(serial.to_vec().into());
    csr.params = params;
    let certificate = csr
        .signed_by(&issuer, &issuer_key)
        .map_err(|_| invalid("device certificate signing failed"))?;
    // Validate against the ORIGINAL CA bytes, not the reconstructed issuer.
    // This detects a wrong CA key as well as profile/chain failures before a
    // certificate can be registered for access.
    let mut roots = rustls::RootCertStore::empty();
    for ca in CertificateDer::pem_slice_iter(ca_pem.as_bytes()) {
        roots
            .add(ca.map_err(|_| invalid("issuer PEM invalid"))?)
            .map_err(|_| invalid("issuer trust anchor invalid"))?;
    }
    let verifier = rustls::server::WebPkiClientVerifier::builder_with_provider(
        std::sync::Arc::new(roots),
        super::provider(),
    )
    .build()
    .map_err(|_| invalid("issuer verifier invalid"))?;
    verifier
        .verify_client_cert(
            certificate.der(),
            &[],
            UnixTime::since_unix_epoch(Duration::from_secs(now)),
        )
        .map_err(|_| {
            invalid("signed device certificate does not verify against the configured CA")
        })?;
    Ok(IssuedDevice {
        certificate_pem: certificate.pem(),
        record: DeviceRecord {
            device_id: device_id.into(),
            certificate_sha256: hex::encode(Sha256::digest(certificate.der().as_ref())),
            not_after_unix_secs: not_after,
            revoked: false,
        },
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn signed_csr_cannot_choose_server_or_ca_certificate_policy() {
        let mut ca_params = CertificateParams::new(Vec::<String>::new()).unwrap();
        ca_params.is_ca = IsCa::Ca(rcgen::BasicConstraints::Unconstrained);
        ca_params.key_usages = vec![KeyUsagePurpose::KeyCertSign];
        let ca_key = KeyPair::generate_for(&rcgen::PKCS_ED25519).unwrap();
        let ca = ca_params.self_signed(&ca_key).unwrap();
        let mut requested = CertificateParams::new(vec!["requested-server.test".into()]).unwrap();
        requested.extended_key_usages = vec![ExtendedKeyUsagePurpose::ServerAuth];
        requested.key_usages = vec![KeyUsagePurpose::KeyCertSign];
        let device_key = KeyPair::generate_for(&rcgen::PKCS_ED25519).unwrap();
        let request = requested
            .serialize_request(&device_key)
            .unwrap()
            .pem()
            .unwrap();
        let now = super::super::registry::unix_now().unwrap();
        let issued = sign_csr(
            "device-a",
            &request,
            &ca.pem(),
            &ca_key.serialize_pem(),
            now,
            300,
        )
        .unwrap();
        let actual = CertificateParams::from_ca_cert_pem(&issued.certificate_pem).unwrap();
        assert_eq!(
            actual.extended_key_usages,
            vec![ExtendedKeyUsagePurpose::ClientAuth]
        );
        assert_eq!(actual.key_usages, vec![KeyUsagePurpose::DigitalSignature]);
        assert!(actual.subject_alt_names.is_empty());
        assert!(matches!(actual.is_ca, IsCa::NoCa));
        // Change signature bytes while keeping valid PEM and CSR structure.
        let mut lines: Vec<String> = request.lines().map(str::to_owned).collect();
        let line = lines.len() - 2;
        let old = lines[line].as_bytes()[0];
        lines[line].replace_range(..1, if old == b'A' { "B" } else { "A" });
        assert!(sign_csr(
            "device-a",
            &lines.join("\n"),
            &ca.pem(),
            &ca_key.serialize_pem(),
            now,
            300
        )
        .is_err());
    }

    #[cfg(unix)]
    #[test]
    fn private_output_rejects_overwrite_symlink_and_writable_ancestry() {
        use std::os::unix::fs::{symlink, PermissionsExt};
        let dir = tempfile::tempdir().unwrap();
        let key = dir.path().join("device.key");
        write_private_new(&key, b"synthetic private material").unwrap();
        assert_eq!(
            std::fs::metadata(&key).unwrap().permissions().mode() & 0o777,
            0o600
        );
        assert!(write_private_new(&key, b"replacement").is_err());
        let link = dir.path().join("alias.key");
        symlink(&key, &link).unwrap();
        assert!(write_private_new(&link, b"replacement").is_err());
        assert_eq!(std::fs::read(&key).unwrap(), b"synthetic private material");
        let ancestor = dir.path().join("shared");
        std::fs::create_dir(&ancestor).unwrap();
        let child = ancestor.join("private");
        std::fs::create_dir(&child).unwrap();
        std::fs::set_permissions(&ancestor, std::fs::Permissions::from_mode(0o777)).unwrap();
        std::fs::set_permissions(&child, std::fs::Permissions::from_mode(0o700)).unwrap();
        assert!(write_private_new(&child.join("secret"), b"must not be written").is_err());
        std::fs::set_permissions(&ancestor, std::fs::Permissions::from_mode(0o700)).unwrap();
        assert!(!child.join("secret").exists());
    }
}
